import{_ as a,o as t,c as s,a5 as i}from"./chunks/framework.DrDMl0tG.js";const p=JSON.parse('{"title":"Benchmark Example: Articulated System","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/benchmark/articulated_system_benchmark.md","filePath":"sections/examples/benchmark/articulated_system_benchmark.md"}'),r={name:"sections/examples/benchmark/articulated_system_benchmark.md"};function n(l,e,h,d,o,c){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="benchmark-example-articulated-system" tabindex="-1">Benchmark Example: Articulated System <a class="header-anchor" href="#benchmark-example-articulated-system" aria-label="Permalink to &quot;Benchmark Example: Articulated System&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Headless timing run for articulated-dynamics workloads. It runs several fixed scenes and prints the time per step of each through <code>raisim::print_timediff</code>. Use it for articulated-system timing checks.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>articulated_system_benchmark</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run it on one thread for benchmark comparisons:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OMP_NUM_THREADS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPENBLAS_NUM_THREADS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./build-examples/examples/articulated_system_benchmark</span></span></code></pre></div><p>On Windows, run <code>articulated_system_benchmark.exe</code> instead. The example takes no arguments and does not use RaisimServer.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><p>The example times these scenes in order:</p><ul><li>ANYmal standing on the ground, then the same robot after the ground is removed (1,000,000 steps each).</li><li>Atlas falling with and without the ground (100,000 steps each); the average contact count is printed as well.</li><li>Chains of 10 and 20 spring-loaded ball-joint links (30 and 60 DOF; 100,000 steps each).</li></ul>',12)])])}const u=a(r,[["render",n]]);export{p as __pageData,u as default};
